put('frontend/e2e/public-collections.spec.ts','''import {expect,test,type Page} from '@playwright/test'
import AxeBuilder from '@axe-core/playwright'
import {roadmapLogin,roadmapApi,roadmapOrigin,roadmapFixture} from './roadmap-profile'
import {sql} from './db'
import {capturePage} from './capture-page'
async function prepare(page:Page,suffix:string){await roadmapLogin(page);const f=roadmapFixture(),id=crypto.randomUUID(),link='f33-'+suffix;sql(`DELETE FROM collections WHERE "tenantId"='${f.tenantId}'; INSERT INTO links (id,"tenantId","ownerId","canonicalUrl",name,description,"networkId","nicheId",status,"occupiesSlot","everPublished","updatedAt") SELECT '${link}','${f.tenantId}',(SELECT id FROM users WHERE "tenantId"='${f.tenantId}' AND id<>'${f.ownerId}' LIMIT 1),'https://example.com/${link}','Comunidade pública','Encontros e materiais de estudo',(SELECT id FROM networks WHERE "tenantId"='${f.tenantId}' LIMIT 1),(SELECT id FROM niches WHERE "tenantId"='${f.tenantId}' AND "requiresAge"=false LIMIT 1),'PUBLISHED',false,true,NOW()`);const saved=await roadmapApi(page,'/me/favorites/'+link,'PUT');expect(saved.status).toBe(200);expect((await roadmapApi(page,'/me/collections','POST',{id,name:'Estudos'})).status).toBe(200);expect((await roadmapApi(page,'/me/collections/'+id+'/items/'+saved.body.favoriteId,'PUT',{expectedVersion:0})).status).toBe(200);await page.goto(roadmapOrigin+'/painel/favoritos');await page.getByRole('tab',{name:'Coleções',exact:true}).click();await page.getByRole('region',{name:'Suas coleções'}).getByRole('button',{name:'Estudos',exact:true}).click();return {id,link,slug:'estudos-'+suffix,favorite:saved.body.favoriteId}}
async function fill(page:Page,slug:string){await page.getByRole('button',{name:'Publicar coleção',exact:true}).click();const dialog=page.getByRole('dialog',{name:'Compartilhar coleção'});await dialog.getByLabel('Nome do curador').fill('Ana Curadora');await dialog.getByLabel('Endereço da coleção').fill(slug);return dialog}
test('F33-E01/T01/T02/T03/T04/T05/T06 publica seleção e revoga, autoria distinta e elegibilidade viva',async({page,browser},info)=>{const f=await prepare(page,'journey-'+(info.project.name.includes('mobile')?'m':'d'));const dialog=await fill(page,f.slug);await dialog.getByRole('button',{name:'Publicar seleção'}).click();await expect(dialog).not.toBeVisible();await expect(page.getByRole('link',{name:'Ver coleção pública'})).toBeVisible();const context=await browser.newContext(),visitor=await context.newPage();try{await visitor.goto(roadmapOrigin+'/colecoes/'+f.slug);await expect(visitor.getByRole('heading',{name:'Estudos',exact:true})).toBeVisible();await expect(visitor.getByText('Curadoria de Ana Curadora')).toBeVisible();await expect(visitor.getByText('Publicado por outro anunciante')).toBeVisible();await capturePage(visitor,info.outputPath('collection-public.png'));const axe=await new AxeBuilder({page:visitor}).include('main').withTags(['wcag2a','wcag2aa','wcag21aa']).analyze();expect(axe.violations.map(v=>v.id)).toEqual([]);sql(`UPDATE links SET status='UNAVAILABLE' WHERE id='${f.link}'`);await visitor.reload();await expect(visitor.getByText('Sem links disponíveis no momento.')).toBeVisible();expect(await visitor.content()).not.toContain('Comunidade pública');await page.getByRole('button',{name:'Configurar publicação'}).click();await page.getByRole('button',{name:'Tornar privada',exact:true}).click();await expect(page.getByRole('dialog')).not.toBeVisible();const response=await visitor.goto(roadmapOrigin+'/colecoes/'+f.slug);expect(response?.status()).toBe(404)}finally{await context.close()}})
test('F33-E02/I02 sem sessão/outro dono e rascunho secreto fora do público',async({page,browser},info)=>{const f=await prepare(page,'isolation-'+(info.project.name.includes('mobile')?'m':'d'));const context=await browser.newContext(),visitor=await context.newPage();try{await visitor.goto(roadmapOrigin);expect((await roadmapApi(visitor,'/me/collections/'+f.id)).status).toBe(401);await roadmapLogin(visitor,true);expect((await roadmapApi(visitor,'/me/collections/'+f.id)).status).toBe(404);const dialog=await fill(page,f.slug);await dialog.getByRole('button',{name:'Publicar seleção'}).click();await expect(dialog).not.toBeVisible();await roadmapApi(page,'/me/collections/'+f.id,'PATCH',{name:'private-title-sentinel',expectedVersion:2});await visitor.goto(roadmapOrigin+'/colecoes/'+f.slug);expect(await visitor.content()).not.toContain('private-title-sentinel');const body=(await roadmapApi(visitor,'/collections/'+f.slug)).body;expect(JSON.stringify(body)).not.toContain(f.favorite);expect(body.items[0]).not.toHaveProperty('ownerId')}finally{await context.close()}})
test('F33-E03/C01 falha real de rede mantém formulário; teclado, idade e reflow',async({page},info)=>{const f=await prepare(page,'recovery-'+(info.project.name.includes('mobile')?'m':'d'));const dialog=await fill(page,f.slug);await page.route('**/bff/v1/me/collections/*/publish',route=>route.abort('failed'));await dialog.getByRole('button',{name:'Publicar seleção'}).click();await expect(dialog.getByRole('alert')).toContainText('Sem conexão');await expect(dialog.getByLabel('Nome do curador')).toHaveValue('Ana Curadora');await page.unrouteAll({behavior:'wait'});await dialog.getByRole('checkbox').check();await dialog.getByRole('button',{name:'Publicar seleção'}).focus();await page.keyboard.press('Enter');await expect(dialog).not.toBeVisible();await page.goto(roadmapOrigin+'/colecoes/'+f.slug);await expect(page.getByRole('button',{name:'Tenho 18 anos ou mais'})).toBeVisible();expect(await page.content()).not.toContain('Comunidade pública');await page.getByRole('button',{name:'Tenho 18 anos ou mais'}).click();await expect(page.getByRole('heading',{name:'Estudos',exact:true})).toBeVisible();await page.setViewportSize({width:320,height:844});await page.addStyleTag({content:'html{font-size:200%}'});expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1)).toBe(true);await capturePage(page,info.outputPath('collection-reflow.png'))})
''')
p=r/'frontend/playwright.config.ts';s=p.read_text().replace('testMatch: /share-kit','testMatch: /public-collections\\.spec\\.ts|share-kit');p.write_text(s,encoding='utf-8')
